# CELL 5: GII SELF-TEST   (Eir 2.0.13)
#
# Four hand-calculated cases. No CIF files, no database, no I/O.
#
# The three indices are different quantities and the arithmetic is set out
# below, so a failure says which one moved:
#
#   GII   = sqrt( mean( d_i^2 ) )                  d_i = BVS_i - V_i
#   WAGII = sqrt( sum(occ_i * d_i^2) / sum(occ_i) )
#   bvs_discrepancy = sum(|d_i|) / sum(V_i)        pre-1.7.5, kept only for
#                                                  comparison with old output
#
# v2.0.13: a FAILING test now raises. It used to print 'FAIL - check the
# paste' and return False, with nothing reading the return value, so a
# broken instability index would have run a whole batch and reported
# numbers. That is the fault VALIDATE_SHELL had when bv_shell_cn was
# deleted under three passing checks.
#
# v2.0.13: case 3 added. WAGII exists for sites SHARED between species and
# no case tested one - every site in the old fixture held a single element.
# Case 4 covers zero occupancy, which must be excluded outright rather than
# weighted to nearly nothing.


def _test_gii():
    """Hand-calculated GII cases. Raises AssertionError on any mismatch."""
    problems = []

    def _check(name, got, want, tol=5e-4):
        if got is None:
            problems.append(f'{name}: None (expected {want:.4f})')
        elif abs(got - want) > tol:
            problems.append(f'{name}: {got:.4f} (expected {want:.4f})')

    # ---- cases 1 and 2: three ordered sites ----------------------------
    # deviations by hand: Na1 +0.15, Cr1 -0.15, Na2 -0.10 v.u.
    #   GII  = sqrt((0.0225 + 0.0225 + 0.0100)/3)          = 0.13540
    #   disc = (0.15 + 0.15 + 0.10) / (1 + 3 + 1)          = 0.08000
    #   WAGII at occ 0.5/1.0/0.5:
    #        = sqrt((0.5*0.0225 + 0.0225 + 0.5*0.0100)/2)  = 0.13919
    fake = {'test_block': {
        (0.0, 0.0, 0.00): {'elements': ['Na'], 'labels': ['Na1'],
                           'element_data': {'Na': {'valence': 1, 'bvs': 1.15}}},
        (0.0, 0.0, 0.50): {'elements': ['Cr'], 'labels': ['Cr1'],
                           'element_data': {'Cr': {'valence': 3, 'bvs': 2.85}}},
        (0.0, 0.0, 0.25): {'elements': ['Na'], 'labels': ['Na2'],
                           'element_data': {'Na': {'valence': 1, 'bvs': 0.90}}},
    }}
    full = {'Na1': {'occupancy': 1.0}, 'Cr1': {'occupancy': 1.0},
            'Na2': {'occupancy': 1.0}}
    r1 = calculate_global_instability_index(
        fake, site_occupancies=full)['test_block']
    _check('case 1 GII', r1.get('gii'), 0.1354)
    _check('case 1 bvs_discrepancy', r1.get('bvs_discrepancy'), 0.0800)
    if r1.get('wagii') is None or abs(r1['wagii'] - r1['gii']) > 1e-12:
        problems.append('case 1: WAGII must equal GII exactly when every '
                        'occupancy is 1.0')

    part = {'Na1': {'occupancy': 0.5}, 'Cr1': {'occupancy': 1.0},
            'Na2': {'occupancy': 0.5}}
    r2 = calculate_global_instability_index(
        fake, site_occupancies=part)['test_block']
    _check('case 2 GII', r2.get('gii'), 0.1354)
    _check('case 2 WAGII', r2.get('wagii'), 0.1392)

    # ---- case 3: one site shared between two species -------------------
    # This is what WAGII is FOR. A 5% Mn impurity on a 95% Fe site is asked
    # what its sum would be in a cavity the Fe sizes, and answers with
    # something impossible; unweighted, that phantom carries the same
    # weight as the majority it sits among.
    #   d(Fe) = -0.10, d(Mn) = +2.00
    #   GII   = sqrt((0.0100 + 4.0000)/2)                  = 1.41598
    #   WAGII = sqrt((0.95*0.0100 + 0.05*4.0000)/1.00)     = 0.45771
    shared = {'test_block': {
        (0.0, 0.0, 0.0): {'elements': ['Fe', 'Mn'], 'labels': ['Fe1', 'Mn1'],
                          'element_data': {
                              'Fe': {'valence': 3, 'bvs': 2.90},
                              'Mn': {'valence': 2, 'bvs': 4.00}}},
    }}
    occ3 = {'Fe1': {'occupancy': 0.95}, 'Mn1': {'occupancy': 0.05}}
    r3 = calculate_global_instability_index(
        shared, site_occupancies=occ3)['test_block']
    _check('case 3 GII', r3.get('gii'), 1.4160)
    _check('case 3 WAGII', r3.get('wagii'), 0.4577)
    if r3.get('gii') and r3.get('wagii') and r3['gii'] <= r3['wagii']:
        problems.append('case 3: GII should exceed WAGII on a shared site; '
                        'if it does not, the occupancy weighting is not '
                        'reaching the minority species')

    # ---- case 4: a site refined to zero occupancy ----------------------
    # There is no atom there, so its sum describes an atom that does not
    # exist. It must be EXCLUDED, not weighted to nearly nothing.
    zero = {'test_block': {
        (0.0, 0.0, 0.0): {'elements': ['Na'], 'labels': ['Na1'],
                          'element_data': {'Na': {'valence': 1, 'bvs': 1.15}}},
        (0.0, 0.0, 0.5): {'elements': ['Yb'], 'labels': ['Yb1'],
                          'element_data': {'Yb': {'valence': 3, 'bvs': 6.87}}},
    }}
    occ4 = {'Na1': {'occupancy': 1.0}, 'Yb1': {'occupancy': 0.0}}
    r4 = calculate_global_instability_index(
        zero, site_occupancies=occ4)['test_block']
    _check('case 4 GII (absent atom excluded)', r4.get('gii'), 0.1500)
    if r4.get('n_sites_zero_occupancy') != 1:
        problems.append('case 4: n_sites_zero_occupancy '
                        f"{r4.get('n_sites_zero_occupancy')} (expected 1)")

    # ---- verdict -------------------------------------------------------
    print('GII SELF-TEST')
    print(f"  case 1  ordered, occ 1.0    GII {r1.get('gii'):.4f}  "
          f"WAGII {r1.get('wagii'):.4f}  disc {r1.get('bvs_discrepancy'):.4f}")
    print(f"  case 2  ordered, occ 0.5    GII {r2.get('gii'):.4f}  "
          f"WAGII {r2.get('wagii'):.4f}")
    print(f"  case 3  shared site 95:5    GII {r3.get('gii'):.4f}  "
          f"WAGII {r3.get('wagii'):.4f}   <- why WAGII exists")
    print(f"  case 4  one site at occ 0   GII {r4.get('gii'):.4f}  "
          f"({r4.get('n_sites_zero_occupancy')} absent atom excluded)")
    if problems:
        raise AssertionError('GII self-test FAILED:\n  - '
                             + '\n  - '.join(problems))
    print('  PASSED')
    return True


_test_gii()
